extern s32 (*gDataBankTranslate)(s32, s32);

/* Returns key unchanged if it is in segment 0x80 or 0xB0; otherwise translates it through the data-bank callback. */ s32 resolveResourceKey(s32 key) {
    s32 segment;
    s32 resolved;

    resolved = key;
    segment = resolved & 0xFF000000;
    if ((segment != 0x80000000) & (segment != 0xB0000000)) {
        resolved = gDataBankTranslate(resolved, resolved);
    }
    return resolved;
}
